PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry scaled_dot_product_attention(
    .param .u64 Q_ptr,
    .param .u64 K_ptr,
    .param .u64 V_ptr,
    .param .u64 Out_ptr,
    .param .u32 N_elements
)
{
    // -------------------------------------------------
    // Thread index
    // -------------------------------------------------
    .reg .u32   %r<5>;
    .reg .u64   %rd<10>;

    // tid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32    %r1, %ctaid.x;
    mov.u32    %r2, %ntid.x;
    mul.lo.u32 %r3, %r1, %r2;
    mov.u32    %r4, %tid.x;
    add.u32    %r0, %r3, %r4;        // %r0 = global thread id

    // Load N_elements
    ld.param.u32    %r5, [N_elements];
    setp.ge.u32     %p1, %r0, %r5;
    @%p1 bra        DONE;

    // Load pointer arguments
    ld.param.u64    %rd1, [Q_ptr];
    ld.param.u64    %rd2, [K_ptr];
    ld.param.u64    %rd3, [V_ptr];
    ld.param.u64    %rd4, [Out_ptr];

    // Compute byte offset: each half = 2 bytes
    cvt.u64.u32     %rd5, %r0;
    mul.lo.u64      %rd6, %rd5, 2;

    // Load half from Q (fp16) and store to output
    .reg .f16   %f<2>;
    add.u64     %rd7, %rd1, %rd6;
    ld.global.f16   %f1, [%rd7];
    add.u64     %rd8, %rd4, %rd6;
    st.global.f16   [%rd8], %f1;

DONE:
    ret;
}
'''

